 public static void CheckSavedProfile(string[] args){
  try{string profile=args[Array.IndexOf(args,"--data-dir")+1],report=args[Array.IndexOf(args,"--report")+1];using var disk=new Store(profile);var state=disk.Load();var view=RulerViewPreferences.Load(Path.Combine(profile,"ruler-view.json"),true);File.WriteAllText(report,JsonSerializer.Serialize(new{view.SelfName,ContactName=state.Rows.Single().Name,view.Motion}));}catch{Environment.ExitCode=1;}
 }
